INSERT INTO cosmetics ("source_id", "type", "name", "coin_price", "rarity", "preview", "is_active", "reward_only", "asset_kind", "asset_url", created_at, updated_at)
SELECT "source_id", "type", "name", "coin_price", "rarity", "preview", "is_active", "reward_only", "asset_kind", "asset_url", strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM seed
WHERE NOT EXISTS (SELECT 1 FROM cosmetics AS stored WHERE stored."source_id" = seed."source_id")
ON CONFLICT (source_id) DO NOTHING;

