INSERT INTO achievement_tiers ("source_id", "tier", "target", "reward_coins", "reward_cosmetic", "achievements_id", "position")
SELECT "source_id", "tier", "target", "reward_coins", "reward_cosmetic", "achievements_id", "position" FROM seed
WHERE NOT EXISTS (SELECT 1 FROM achievement_tiers AS stored WHERE stored."achievements_id" = seed."achievements_id" AND stored."tier" = seed."tier")
  AND EXISTS (SELECT 1 FROM achievements WHERE source_id = seed.achievements_id)
ON CONFLICT (source_id) DO NOTHING;

