INSERT INTO gifts ("source_id", "name", "icon", "coin_price", "pk_points", "diamond_price", "is_active", "effect3d", "interactive", "animation_key", "combo_multiplier", "category", "bond_points", "bond_minimum_days", "theme", "rarity", "limited_edition_active", "limited_edition_total", "limited_edition_remaining", "tradable", "upgradeable", "achievement_gift", "pet_gift", "vehicle_gift", created_at, updated_at)
SELECT "source_id", "name", "icon", "coin_price", "pk_points", "diamond_price", "is_active", "effect3d", "interactive", "animation_key", "combo_multiplier", "category", "bond_points", "bond_minimum_days", "theme", "rarity", "limited_edition_active", "limited_edition_total", "limited_edition_remaining", "tradable", "upgradeable", "achievement_gift", "pet_gift", "vehicle_gift", strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now') FROM seed
